import { Box } from "@mui/material";
import HeroSection from "../components/fellowship/HeroSection";
import SpecialtiesSection from "../components/fellowship/SpecialtiesSection";
import WhyChooseSection from "../components/fellowship/WhyChooseSection";
import FeaturedProgramsSection from "../components/fellowship/FeaturedProgramsSection";
import SelectedProgramSection from "../components/fellowship/SelectedProgramSection";
import PartnersSection from "../components/fellowship/PartnersSection";
import TestimonialsSection from "../components/fellowship/TestimonialsSection";
import FooterCtaSection from "../components/fellowship/FooterCtaSection";
import type { Program, Specialty } from "../types/fellowship";

interface LandingPageProps {
  specialtyId: string | null;
  specialty: Specialty | null;
  programs: Program[];
  selectedProgram: Program | null;
  onViewPrograms: (specialtyId: string) => void;
  onLearnMore: (programId: string) => void;
  onClearProgram: () => void;
  onClearSpecialty: () => void;
}

export default function LandingPage({
  specialtyId,
  specialty,
  programs,
  selectedProgram,
  onViewPrograms,
  onLearnMore,
  onClearProgram,
  onClearSpecialty,
}: LandingPageProps) {
  return (
    <Box component="main">
      <HeroSection specialty={specialty} />
      <SpecialtiesSection
        selectedSpecialtyId={specialtyId}
        onViewPrograms={onViewPrograms}
      />
      <WhyChooseSection />
      <Box id="featured-programs">
        <FeaturedProgramsSection
          programs={programs}
          title={specialty ? `${specialty.name} Fellowship Programs` : undefined}
          showViewAll={Boolean(specialty)}
          onLearnMore={onLearnMore}
          onViewAll={onClearSpecialty}
          viewAllLabel="View All Specialities →"
        />
      </Box>
      {selectedProgram && (
        <Box id="selected-program">
          <SelectedProgramSection
            program={selectedProgram}
            specialtyPrograms={programs}
            onSelectProgram={onLearnMore}
            onClose={onClearProgram}
          />
        </Box>
      )}
      <PartnersSection />
      <TestimonialsSection />
      <FooterCtaSection />
    </Box>
  );
}
